INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'sec.agent', '安全性代理', 'shield', 'IT 必裝', '資訊部 · 資安小組', '4.2.1', NULL, 'required_missing', true, false, 0, true, '全體員工（強制）', '84 MB', '2026-09-12', '端點防護與弱點掃描代理。公司政策要求所有公司配發設備安裝並保持啟用，未安裝將於 7 日後限制內網存取。', '', '{"used": 412, "total": 500}'::jsonb, '["端點防護常駐", "每週弱點掃描", "USB 管制", "磁碟加密狀態回報"]'::jsonb, '["讀取本機程序清單", "常駐背景服務", "回報裝置合規狀態"]'::jsonb, '[{"ver": "4.2.1", "date": "2026-09-12", "note": "修正與 VPN 用戶端並存時的網路延遲"}, {"ver": "4.2.0", "date": "2026-08-28", "note": "新增 USB 大量儲存裝置管制"}, {"ver": "4.1.3", "date": "2026-07-15", "note": "弱點掃描改為離峰時段執行"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'it.remote', '遠端支援', 'headset', 'IT 必裝', '資訊部 · 服務台', '2.0.4', NULL, 'installed', true, false, 0, true, '全體員工（強制）', '22 MB', '2026-08-30', '讓服務台在你同意後連線到這台電腦排除問題。每次連線都需要你按下允許，並會留下錄影紀錄。', '{"owner": "資訊部 · 服務台", "ext": "1999", "updated": "2026-08-30", "sop": "IT 服務台作業說明（知識庫「IT」分類）", "video": "允許連線的操作示範 · 40 秒", "checklist": ["先撥分機 1999 開案，服務台會給你一組 6 碼連線代碼", "把機密文件或個人視窗關掉：連線全程會錄影存查", "現場作業中的機台程式不要關，服務台需要看到現況"], "steps": [{"t": "輸入連線代碼", "d": "開啟後輸入服務台給的 6 碼代碼，代碼 10 分鐘內有效。", "shot": "截圖：輸入連線代碼"}, {"t": "按下允許", "d": "跳出同意視窗時要自己按「允許」，服務台無法代按。不按就不會連上。", "shot": "截圖：同意連線視窗"}, {"t": "過程中", "d": "畫面右上角有連線中標示與紅點錄影標示。任何時候按「中斷」立刻停止。", "shot": "截圖：連線中的狀態列"}, {"t": "結束", "d": "服務台結束後會顯示本次錄影編號，寫在工單上方便後續追。", "shot": "截圖：連線結束摘要"}], "can": ["服務台看你的畫面並在你同意後操作", "雙向傳送檔案（有紀錄）", "連線錄影事後調閱（需主管與資安同意）"], "cannot": ["服務台在你未同意時連線", "無人值守連線（一定要有人按允許）", "連線到產線 PLC 或量測儀器"], "faq": [{"q": "連線代碼顯示無效", "a": "代碼逾時 10 分鐘就失效，回電 1999 要新的一組。"}, {"q": "連線後畫面卡住", "a": "按「中斷」再重連一次；若卡在特定程式，先關掉該程式再連。"}, {"q": "我可以事後看錄影嗎", "a": "可以，但要主管與資安小組同意。用工單編號向服務台申請。"}]}', '{"used": 500, "total": 500}'::jsonb, '["畫面共享（需逐次同意）", "檔案傳送", "連線錄影存查"]'::jsonb, '["擷取畫面（同意後）", "控制滑鼠鍵盤（同意後）"]'::jsonb, '[{"ver": "2.0.4", "date": "2026-08-30", "note": "連線前的同意視窗改為需明確點選"}, {"ver": "2.0.0", "date": "2026-06-11", "note": "改寫連線核心，延遲降低約 40%"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'ai.assistant', 'AI 助理', 'sparkle', '生產力', '資訊部 · 應用整合', '2.4.0', '2.2.1', 'update', false, false, 0, false, '經核准的部門（生產部已核准）', '48 MB', '2026-09-15', '以公司內部文件與系統資料為基礎的問答助理。可查規章、擬信件草稿、彙整單據摘要；回答會附上引用來源。', '', '{"used": 186, "total": 250}'::jsonb, '["內部文件問答", "信件與公告草稿", "單據摘要", "會議紀錄整理"]'::jsonb, '["讀取你有權限的文件", "讀取你的單據清單", "不寫入任何系統"]'::jsonb, '[{"ver": "2.4.0", "date": "2026-09-15", "note": "回答附引用來源，並可追溯到原始文件段落"}, {"ver": "2.3.0", "date": "2026-08-20", "note": "支援單據摘要，串接銷貨與合約資料"}, {"ver": "2.2.1", "date": "2026-07-30", "note": "修正長文件截斷問題"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'inbox', 'Inbox', 'inbox', '溝通', '資訊部 · 平台組', '3.1.2', NULL, 'installed', false, true, 7, true, '全體員工', '16 MB', '2026-09-08', '把各系統的通知與待辦集中在一處：待簽核單據、IT 要求、公告、系統維護通知。處理完會同步回原系統。', '', '{"used": 498, "total": 500}'::jsonb, '["跨系統通知匯總", "待辦一鍵前往", "免打擾時段", "桌面通知"]'::jsonb, '["接收各系統通知", "顯示桌面通知"]'::jsonb, '[{"ver": "3.1.2", "date": "2026-09-08", "note": "免打擾時段可依部門班表自動套用"}, {"ver": "3.0.0", "date": "2026-07-02", "note": "改為集中式通知匯流，支援 11 個來源系統"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'qr.gen', 'QRCode 生成器', 'qr', '生產力', '生產部 · 自動化小組', '1.3.0', NULL, 'installed', false, true, 0, false, '生產部、倉管、品保', '4 MB', '2026-06-20', '產生料號、設備、儲位的 QRCode 與條碼，可批次由 Excel 匯入並輸出列印版面。產線標籤機的版型已內建。', '{"owner": "生產部 · 自動化小組 張伯彥", "ext": "2481", "updated": "2026-08-30", "sop": "SOP-PR-014 標籤列印作業（產線白皮夾／知識庫可查）", "video": "標籤機直印示範 · 1 分 40 秒", "checklist": ["標籤機電源開啟、紙捲方向正確（感熱面朝上）", "手上有正確的料號清單或 Excel 檔", "確認要印的版型：料號、儲位、設備三種不同，印錯不能重貼"], "steps": [{"t": "選版型", "d": "左側先選料號／儲位／設備。版型決定尺寸與欄位，選錯會印不進標籤框。", "shot": "截圖：三種版型選擇畫面"}, {"t": "單筆或批次", "d": "單筆直接輸入料號；批次按「匯入 Excel」，第一列必須是欄位名稱，上限 5000 筆。", "shot": "截圖：批次匯入與欄位對應"}, {"t": "檢查預覽", "d": "預覽會顯示實際列印尺寸。料號超過 20 字會自動縮小字級，太小就改用兩行版型。", "shot": "截圖：列印預覽與尺寸標示"}, {"t": "輸出", "d": "產線用「標籤機直印」；要留檔或送外部用「輸出 PDF」。直印不會留檔，需要留檔請兩者都做一次。", "shot": "截圖：輸出方式選單"}], "can": ["批次由 Excel 產生 5000 筆以內的標籤", "同一批次混用不同料號、相同版型", "輸出 PDF／PNG 給廠商"], "cannot": ["自訂新版型（需向自動化小組申請，約 3 個工作日）", "印含客戶 LOGO 的標籤（要走品保核可）", "一次混印不同版型"], "faq": [{"q": "按了直印但標籤機沒動作", "a": "先看標籤機面板是否顯示待命。九成是紙捲沒對到感測器：把紙捲退出 5 公分重新送入，再按一次直印。仍無反應打分機 2481。"}, {"q": "印出來是空白標籤", "a": "紙捲裝反了（感熱面朝下）。翻面重裝，已印掉的空白標籤直接丟棄，不用回報。"}, {"q": "匯入 Excel 顯示欄位對不到", "a": "第一列必須是欄位名稱且不能有合併儲存格。用「下載範本」重貼一次資料最快。"}, {"q": "QRCode 掃不出來", "a": "多半是縮放列印。印表機設定要用 100%，不要選「符合頁面大小」。"}]}', '{"used": 64, "total": 100}'::jsonb, '["單筆與批次產生", "料號／儲位／設備三種版型", "輸出 PDF 與 PNG", "標籤機直印"]'::jsonb, '["讀取本機檔案（你選擇的）", "使用印表機"]'::jsonb, '[{"ver": "1.3.0", "date": "2026-06-20", "note": "新增儲位版型與批次匯入上限提高到 5000 筆"}, {"ver": "1.2.0", "date": "2026-04-08", "note": "支援標籤機直印"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'vault', '密碼保管庫', 'key', 'IT 必裝', '資訊部 · 資安小組', '5.0.2', NULL, 'installed', true, false, 0, true, '全體員工（強制）', '31 MB', '2026-09-01', '存放公用帳號與系統憑證，依角色授權取用，每次取用都會留存紀錄。個人密碼也可放這裡。', '', '{"used": 500, "total": 500}'::jsonb, '["公用帳號共享", "取用紀錄留存", "瀏覽器自動填入", "到期提醒"]'::jsonb, '["本機加密儲存", "瀏覽器擴充整合"]'::jsonb, '[{"ver": "5.0.2", "date": "2026-09-01", "note": "修正主密碼變更後的同步延遲"}, {"ver": "5.0.0", "date": "2026-08-05", "note": "改用硬體金鑰保護主密鑰"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'asset.query', '資產與設備查詢', 'laptop', '資產', '總務部 · 資產管理', '1.1.4', NULL, 'not_installed', false, false, 0, false, '全體員工', '9 MB', '2026-07-22', '查詢自己名下的公司資產、保固到期日與歸還狀態，也可掃 QRCode 查任一台設備的履歷。', '', '{"used": 121, "total": 300}'::jsonb, '["我的資產清單", "保固與折舊查詢", "掃碼查設備履歷", "報修連結"]'::jsonb, '["讀取資產主檔（你名下）", "使用相機掃碼"]'::jsonb, '[{"ver": "1.1.4", "date": "2026-07-22", "note": "掃碼可直接帶出設備履歷與報修紀錄"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'file.send', '檔案安全傳送', 'upload', 'IT 必裝', '資訊部 · 資安小組', '2.6.0', NULL, 'installed', false, false, 0, true, '全體員工', '12 MB', '2026-08-18', '把大檔或機密檔案傳給外部廠商，連結可設密碼與到期日，傳送紀錄保留一年供稽核。', '{"owner": "資訊部 · 資安小組 陳彥廷", "ext": "1642", "updated": "2026-08-18", "sop": "資安規章 5.4 對外檔案傳送（知識庫「資安」分類）", "video": "設定密碼與到期日 · 1 分 10 秒", "checklist": ["確認檔案可以對外：圖紙與客戶資料需主管書面同意", "密碼要用另一個管道給對方（電話或簡訊），不要寫在同一封信", "單檔上限 20 GB，超過請拆檔"], "steps": [{"t": "選檔案", "d": "拖進視窗或按選擇檔案。會顯示分塊上傳進度，中斷可續傳。", "shot": "截圖：上傳進度與續傳"}, {"t": "設定連結", "d": "設密碼與到期日（預設 7 天）。對外一律要設密碼。", "shot": "截圖：連結設定"}, {"t": "送出並通知", "d": "複製連結貼到信件；勾選「下載通知」對方下載時會收到通知。", "shot": "截圖：連結產生與通知設定"}], "can": ["單檔 20 GB 以內、連結設密碼與到期", "查一年內的傳送與下載紀錄", "提前讓連結失效"], "cannot": ["寄給未經登錄的外部信箱網域（需先申請）", "傳送已被 DLP 標記的機密圖紙", "匿名傳送"], "faq": [{"q": "對方說連結打不開", "a": "先確認是否已過期或已達下載次數上限。在「我的傳送」可延長到期日並重寄。"}, {"q": "上傳到一半中斷", "a": "回到同一個畫面會顯示續傳，不必重選檔案。網路不穩建議改用有線網路。"}, {"q": "被擋下說含機密內容", "a": "這是 DLP 規則。需要外送請附主管同意單向資安小組申請例外，分機 1642。"}]}', '{"used": 233, "total": 500}'::jsonb, '["單檔上限 20 GB", "連結設密碼與到期", "下載通知", "稽核紀錄"]'::jsonb, '["讀取你選擇的檔案", "外網上傳"]'::jsonb, '[{"ver": "2.6.0", "date": "2026-08-18", "note": "單檔上限提高到 20 GB，改為分塊續傳"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'notice.kb', '公告與知識庫', 'book', '溝通', '人資部 · 內部溝通', '4.0.1', '3.8.2', 'update', false, false, 2, true, '全體員工', '14 MB', '2026-09-10', '公司公告、規章、SOP 與教學文件的集中入口，支援離線下載與全文搜尋，必讀公告會要求確認已讀。', '{"owner": "人資部 · 內部溝通 周雅雯", "ext": "1105", "updated": "2026-09-10", "sop": "文件管理辦法 2.1（知識庫「人資」分類）", "video": "離線下載 SOP 到平板 · 50 秒", "checklist": ["必讀公告會擋在進入時，先讀完再按確認，系統會記錄時間", "要帶到現場看的 SOP 先做離線下載，廠區有些地方沒有訊號", "看 SOP 前確認版本：現場作業一律以最新生效版為準"], "steps": [{"t": "找文件", "d": "用全文搜尋，關鍵字會在結果中標示；也可依分類瀏覽。", "shot": "截圖：搜尋結果與命中字"}, {"t": "確認版本", "d": "文件標頭顯示版次與生效日。舊版會有灰色「已停用」標示。", "shot": "截圖：版本與生效日標頭"}, {"t": "離線下載", "d": "按「離線下載」，文件會存在這台裝置，30 天後自動失效以避免看到舊版。", "shot": "截圖：離線下載與有效期"}, {"t": "版本比對", "d": "改版後可用「與上一版比對」看改了哪幾段，現場交接很有用。", "shot": "截圖：版本差異比對"}], "can": ["全文搜尋規章、SOP、教學文件", "離線下載（30 天效期）", "比對兩個版本的差異"], "cannot": ["修改或上傳文件（請洽文件管理員）", "查看其他部門限閱的文件", "列印標示禁止複印的文件"], "faq": [{"q": "搜不到我知道存在的 SOP", "a": "可能是限閱或已停用。改用文件編號搜尋，還是找不到請洽分機 1105。"}, {"q": "離線文件打不開", "a": "超過 30 天效期。連上內網重新下載一次即可。"}, {"q": "必讀公告可以稍後嗎", "a": "可以按稍後，但會記錄未讀並每天提醒，月底未讀清單會寄給主管。"}]}', '{"used": 500, "total": 500}'::jsonb, '["公告必讀確認", "規章與 SOP 全文搜尋", "離線下載", "版本比對"]'::jsonb, '["讀取你有權限的文件庫"]'::jsonb, '[{"ver": "4.0.1", "date": "2026-09-10", "note": "必讀公告改為進入時提示，可稍後但會記錄未讀"}, {"ver": "4.0.0", "date": "2026-09-02", "note": "全文搜尋改寫，支援 SOP 版本比對"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'print.queue', '列印佇列', 'printer', '生產力', '總務部 · 事務機', '1.0.8', NULL, 'not_installed', false, false, 0, false, '全體員工', '6 MB', '2026-05-14', '查看自己送出的列印工作、在任一台事務機刷卡取件，也能看部門的用紙與碳粉統計。', '', '{"used": 88, "total": 300}'::jsonb, '["刷卡取件", "跨機取件", "用量統計", "重印與取消"]'::jsonb, '["讀取列印伺服器佇列", "使用印表機"]'::jsonb, '[{"ver": "1.0.8", "date": "2026-05-14", "note": "支援跨樓層事務機取件"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'translate', '譯文工具', 'globe', '生產力', '資訊部 · 應用整合', '1.2.2', NULL, 'not_installed', false, false, 0, false, '業務部、採購部、專案辦公室', '7 MB', '2026-08-06', '中英日三語互譯，內建公司專有名詞與料號對照表，翻譯內容不送出公司網路之外。', '', '{"used": 47, "total": 150}'::jsonb, '["中英日互譯", "公司術語表", "文件整份翻譯", "選取即譯"]'::jsonb, '["讀取剪貼簿（你觸發時）"]'::jsonb, '[{"ver": "1.2.2", "date": "2026-08-06", "note": "術語表改為每日自動同步"}]'::jsonb, '[]'::jsonb);
INSERT INTO dbo.tool_management (type, tool_no, name, icon, cat, vendor, version, installed_version, state, required, pinned, badge, auto_update, audience, size, updated, description, guide, seats, capabilities, permissions, changelog, usage) VALUES
    ('tool', 'timeclock', '工時與打卡', 'clock', '人事', '人資部 · 出勤', '3.3.0', NULL, 'installed', false, true, 0, true, '全體員工', '11 MB', '2026-09-05', '上下班打卡、查看本月出勤與加班時數。異常打卡會提示補登，補登後送人資覆核。', '{"owner": "人資部 · 出勤 李文華", "ext": "1207", "updated": "2026-09-05", "sop": "人事規章 3.2 出勤與補登（知識庫「人事」分類）", "video": "補登流程示範 · 55 秒", "checklist": ["確認自己的班別（早班／中班／夜班跨日規則不同）", "在廠區內打卡：需要定位權限，車上或廠外打卡會被記為異常", "補登要在異常發生後 3 個工作日內送出"], "steps": [{"t": "打卡", "d": "開啟後按大顆的上班／下班。成功會顯示時間與班別，沒顯示就是沒成功。", "shot": "截圖：打卡主畫面與成功狀態"}, {"t": "看本月出勤", "d": "紅字是異常，灰字是休假。點該日展開可看到原始打卡時間。", "shot": "截圖：本月出勤月曆"}, {"t": "補登", "d": "在異常那天按「補登」，選原因並寫明情況（例：在 3 號廠區支援，忘記帶卡）。", "shot": "截圖：補登表單"}, {"t": "等覆核", "d": "送出後狀態為「待主管覆核」，主管核可才會轉正常。超過 2 天沒動可打分機 1207。", "shot": "截圖：補登狀態追蹤"}], "can": ["查本月與前 6 個月的出勤", "看加班時數與接近上限的預警", "代打卡申請（需主管在系統上核可）"], "cannot": ["自行修改已核可的紀錄", "補登超過 3 個工作日的異常（要走紙本申請）", "查別人的出勤"], "faq": [{"q": "打卡後畫面沒有顯示時間", "d": "", "a": "沒打成功。多半是定位被關：Windows 設定 → 隱私權 → 位置，允許這支工具。重開工具再打一次。"}, {"q": "顯示「不在廠區範圍」", "a": "廠區邊界以圍牆為準，停車場不算。走進廠區再打，或當天走補登。"}, {"q": "夜班跨日算哪一天", "a": "以上班打卡當天為準。23:50 上班、隔天 08:00 下班會歸在前一天。"}]}', '{"used": 500, "total": 500}'::jsonb, '["打卡與補登", "本月工時統計", "加班時數預警", "班表查詢"]'::jsonb, '["讀取你的出勤紀錄", "取得裝置位置（打卡時）"]'::jsonb, '[{"ver": "3.3.0", "date": "2026-09-05", "note": "加班時數接近上限時於狀態列預警"}, {"ver": "3.2.0", "date": "2026-07-18", "note": "異常打卡自動帶出補登表單"}]'::jsonb, '[]'::jsonb);
